self.KB_CONTENT["field:843310"]={"id":"field:843310","ty":"field","sourceId":"843310","title":"進貨資料合併賦予資產編號","ver":"GP4.0.14.0以上","topic":"","keywords":[],"job":"進貨資料拆解賦予資產編號","code":"","answer":"『進貨資料拆解賦予資產編號』：資產進貨後，每一筆資產進貨資料可依數量各給予資產編號 『進貨資料合併賦予資產編號』：資產進貨後，可將多筆同時進貨之相同資產品項，賦予同一資產編號","file":"fields.jsonl"};
