self.KB_CONTENT["field:784242"]={"id":"field:784242","ty":"field","sourceId":"784242","title":"取得成本(稅簽)","ver":"GP4以上","topic":"","keywords":[],"job":"資產調整建立作業","code":"TC075","answer":"* 為因資產調整所需增減的取得成本(稅簽)。* 取得成本(稅簽)=(取得成本(稅簽)(原)/數量(稅簽)(原)) × 調整數量。* 本國幣別金額取位。","file":"fields.jsonl"};
